R=/scratch/jjyeung/orch_n30
date -u +%TZ
echo  | base64 -d > $R/sb_queue/codexq3.sh
tmux kill-session -t sb_codexq; tmux new-session -d -s sb_codexq "bash $R/sb_queue/codexq3.sh"
n=0; for p in $(pgrep -u jjyeung); do c=$(readlink /proc/$p/cwd 2>/dev/null); case "$c" in $R/sb_*) renice -n 10 -p $p >/dev/null 2>&1 && n=$((n+1));; esac; done; echo "reniced by cwd: $n"
ps -u jjyeung -o ni,pcpu,args --sort=-pcpu | head -8 | cut -c1-110
